import "dotenv/config";    //ye line env file ko read karti hian and  process.env main load karti hian
                            //Agar yeh nahi hoga toh:process.env["DATABASE_URL"] undefined milega aur Prisma database se connect nahi kar payega (Connection Error aayega)
import { defineConfig } from "prisma/config";

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: process.env["DATABASE_URL"],
  },
});




